package com.finanscore.notification.application;import jakarta.mail.internet.MimeMessage;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.ByteArrayResource;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Component;@Component public class EmailNotificationSender{private final JavaMailSender mail;private final String from;private final String username;public EmailNotificationSender(JavaMailSender m,@Value("${app.mail.from:no-reply@finanscore.local}")String f,@Value("${spring.mail.username:}")String u){mail=m;from=f;username=u;}public void send(String to,String requestId,String reportId,byte[] pdf)throws Exception{if(to==null||to.isBlank())throw new IllegalArgumentException("Correo de destino vacío");if(username==null||username.isBlank()){System.out.println("[DEMO] SMTP no configurado. Se simula envío a "+to+" para solicitud "+requestId);return;}MimeMessage msg=mail.createMimeMessage();var h=new MimeMessageHelper(msg,true,"UTF-8");h.setFrom(from);h.setTo(to);h.setSubject("Evaluación crediticia completada");h.setText("Tu evaluación "+requestId+" ha finalizado. Adjuntamos el reporte PDF.");h.addAttachment("evaluacion-"+requestId+".pdf",new ByteArrayResource(pdf),"application/pdf");mail.send(msg);}}